import{_ as e,o as a,c as d,a5 as o}from"./chunks/framework.BEZBAInb.js";const m=JSON.parse('{"title":"移动镜头","description":"","frontmatter":{"title":"移动镜头","order":1},"headers":[],"relativePath":"zh/latest/tutorial/script/camera/cam-move.md","filePath":"zh/latest/tutorial/script/camera/cam-move.md","lastUpdated":1788455378000}'),c={name:"zh/latest/tutorial/script/camera/cam-move.md"};function n(s,t,r,i,l,h){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="移动镜头" tabindex="-1">移动镜头 <a class="header-anchor" href="#移动镜头" aria-label="Permalink to &quot;移动镜头&quot;">​</a></h1><h2 id="功能描述" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述" aria-label="Permalink to &quot;功能描述&quot;">​</a></h2><p>将镜头移动到指定的目标镜头位置，并支持可选的过渡动画效果。目标镜头需要在背景场景中添加 <code>KonadoCameraMarker</code> 节点，可以添加多个来表示不同机位，并且要求每个节点都有唯一的镜头名称。<code>KonadoCameraMarker</code> 只保存机位数据，不直接渲染画面。</p><h2 id="语法结构" tabindex="-1">语法结构 <a class="header-anchor" href="#语法结构" aria-label="Permalink to &quot;语法结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cam move [目标镜头ID] [过渡类型] [过渡时间]</span></span></code></pre></div><h2 id="参数详解" tabindex="-1">参数详解 <a class="header-anchor" href="#参数详解" aria-label="Permalink to &quot;参数详解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>目标镜头ID</td><td>是</td><td><code>cam1</code></td><td>要移动到的镜头资源标识符</td></tr><tr><td>过渡类型</td><td>否</td><td><code>linear</code> / <code>ease_in_out</code> / <code>none</code></td><td>过渡动画类型，不填或填 <code>none</code> 表示无动画</td></tr><tr><td>过渡时间</td><td>否</td><td><code>1.0</code> / <code>2.5</code></td><td>过渡动画的持续时间（秒），默认值为 <code>1.0</code></td></tr></tbody></table><h2 id="过渡类型说明" tabindex="-1">过渡类型说明 <a class="header-anchor" href="#过渡类型说明" aria-label="Permalink to &quot;过渡类型说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>不填</td><td>默认无动画，直接切换</td></tr><tr><td><code>none</code></td><td>显式指定无动画</td></tr><tr><td><code>linear</code></td><td>线性过渡</td></tr><tr><td><code>ease_in_out</code></td><td>缓入缓出过渡</td></tr></tbody></table><h2 id="默认值规则" tabindex="-1">默认值规则 <a class="header-anchor" href="#默认值规则" aria-label="Permalink to &quot;默认值规则&quot;">​</a></h2><ul><li>不写过渡类型 → <code>cam_tween_type=&quot;&quot;</code>，<code>cam_tween_time=0.0</code>（无动画）</li><li>写 <code>none</code> → <code>cam_tween_type=&quot;none&quot;</code>，<code>cam_tween_time=0.0</code>（无动画）</li><li>写其他过渡类型但不写时间 → <code>cam_tween_time=1.0</code>（默认1秒）</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cam move cam1</span></span>
<span class="line"><span>cam move cam1 none</span></span>
<span class="line"><span>cam move cam1 linear</span></span>
<span class="line"><span>cam move cam1 linear 1.0</span></span>
<span class="line"><span>cam move cam1 ease_in_out 2.5</span></span></code></pre></div>`,13)])])}const u=e(c,[["render",n]]);export{m as __pageData,u as default};
